<span class="line"><span style="color:#B392F0;">docker</span><span style="color:#9ECBFF;"> run</span><span style="color:#79B8FF;"> -d</span><span style="color:#79B8FF;"> --name</span><span style="color:#9ECBFF;"> container2</span><span style="color:#79B8FF;"> --network</span><span style="color:#9ECBFF;"> mybridge</span><span style="color:#9ECBFF;"> nginx</span></span>
